<?php require dirname(__DIR__).'/config/config.php'; require dirname(__DIR__).'/vendor/autoload.php'; use App\Helpers\Security; use App\Helpers\Audit; Security::requireRole(['administrador','gerente','operador']); if($_SERVER['REQUEST_METHOD']==='POST'){Security::checkCsrf($_POST['csrf']??null);$s=db()->prepare('INSERT INTO motoristas(nome,cnh,validade_cnh,telefone,status) VALUES(?,?,?,?,1)');$s->execute([trim($_POST['nome']),trim($_POST['cnh']),$_POST['validade_cnh']?:null,trim($_POST['telefone'])]);Audit::log('Cadastro de motorista','motoristas',(int)db()->lastInsertId());header('Location: motoristas.php');exit;}$rows=db()->query('SELECT * FROM motoristas ORDER BY nome')->fetchAll();?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Motoristas</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-4"><h1>Motoristas</h1><a href="dashboard.php">← Dashboard</a><form method="post" class="row g-2 card p-3 my-4"><input type="hidden" name="csrf" value="<?=Security::csrf()?>"><div class="col-md-4"><input class="form-control" name="nome" placeholder="Nome" required></div><div class="col-md-2"><input class="form-control" name="cnh" placeholder="CNH" required></div><div class="col-md-2"><input class="form-control" type="date" name="validade_cnh"></div><div class="col-md-2"><input class="form-control" name="telefone" placeholder="Telefone"></div><div class="col-md-2"><button class="btn btn-primary">Salvar</button></div></form><table class="table"><thead><tr><th>Nome</th><th>CNH</th><th>Validade</th><th>Telefone</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=Security::e($r['nome'])?></td><td><?=Security::e($r['cnh'])?></td><td><?=Security::e($r['validade_cnh'])?></td><td><?=Security::e($r['telefone'])?></td></tr><?php endforeach;?></tbody></table></div></body></html>
